            return fbm(p, 4);
        }


void main() {
    // 1. Base Coordinates
    vec2 uv = (gl_FragCoord.xy - 0.5 * u_resolution.xy) / u_resolution.y;
    vec2 initialUV = uv; 

    // 2. Global Camera Transforms


    // Dynamic Param modifiers


    vec2 currentUV = uv; 

    vec3 finalColor = vec3(0.0);
    vec3 layerColor = vec3(0.0);

    // 3. Render Pipeline

    // --- Layer 1: Bio-Digital (Xor) [Xor Neural] ---
    {
        currentUV = uv;
        vec2 layerUV = currentUV;
        float localTime = u_time * 0.56;

            // Original: vec3 p,v;for(float i,z,d,l;i++<1e2;o+=(sin(p.y+vec4(6,1,3,3))+1.)/d)p=z*normalize(FC.rgb*2.-r.xyy),p.z+=9.,p=vec3(atan(p.z,p.x)-t*.1,log(l=length(p))-t*.2,asin(p.y/l))/.1,z+=d=l/6e1*length(max(v=cos(p+sin(p/.24+t)),v.yzx*.1));o=tanh(o/2e4);
            vec3 o = vec3(0.0);
            vec3 p = vec3(0.0);
            vec3 v = vec3(0.0);

            float z_pos = 0.0;
            float d = 0.0;
            float l = 0.0;
            float t = localTime * 0.5;

            // Create 3D fragment coordinates (Shadertoy-style FC.rgb)
            vec3 FC = vec3(gl_FragCoord.xy, 0.0);
            vec3 r = vec3(u_resolution.xy, u_resolution.x);

            // Raymarching loop (100 iterations)
            for(float i = 0.0; i < 100.0; i++) {
                // p=z*normalize(FC.rgb*2.-r.xyy)
                p = z_pos * normalize(FC * 2.0 - r.xyy);

                // p.z+=9.
                p.z += 9.0;

                // p=vec3(atan(p.z,p.x)-t*.1,log(l=length(p))-t*.2,asin(p.y/l))/.1
                l = length(p);
                p = vec3(atan(p.z, p.x) - t * 0.2, log(l) - t * 0.2, asin(clamp(p.y / l, -1.0, 1.0))) / 0.1;

                // z+=d=l/6e1*length(max(v=cos(p+sin(p/.24+t)),v.yzx*.1))
                v = cos(p + sin(p / 0.24 + t));
                vec3 v_yzx_select = v.yzx * 0.1 + (u_treble  * 0.01);
                d = l / 60.0 * length(max(v, v_yzx_select));
                z_pos += d;

                // o+=(sin(p.y+vec4(6,1,3,3))+1.)/d
                // Use .xyz to convert vec4 result to vec3
                o += (sin(vec4(p.y) + vec4(6.0, 1.0, 3.0, 3.0)) + 0.10 + u_bass ).xyz / d;
            }

            // o=tanh(o/2e4)
            vec3 layerColor = tanh(o / 20000.0);

            // Audio reactivity
            float intens = 1.0;
            #ifdef u_intensity
                intens = u_intensity;
            #endif
            layerColor *= intens * (1.0 + u_mid * 0.5 + u_mid * 0.3);

        layerColor *= u_amplitude * (0.8 + u_mid * 0.4);
        finalColor = layerColor;
    }


    // 4. Post Processing
    finalColor *= 1.0 + u_bass * 0.15;
    finalColor += max(vec3(0.0), finalColor * finalColor) * u_glow * 0.5;
    finalColor.rgb = mix(finalColor.rgb, finalColor.gbr, sin(u_colorShift * 2.0 + u_time) * 0.5 + 0.5);
    finalColor *= u_intensity;

    // 5. Feedback Trail (Fixed Box & Brightness)

    vec2 screenUV = gl_FragCoord.xy / u_resolution.xy;

    // 1. STATIONARY SAMPLING (Attached Trails)
    // No zoom, just a tiny bit of bass-driven diffusion to smooth the light
    vec2 diff = (vec2(random(screenUV + u_time), random(screenUV - u_time)) - 0.5) * 0.002 * u_bass;
    vec3 prevColor = texture(u_prev_frame, screenUV + diff).rgb;

    // 2. BORDER FADE (Fix Grey Box)
    vec2 border = smoothstep(vec2(0.0), vec2(0.02), screenUV) * (1.0 - smoothstep(vec2(0.98), vec2(1.0), screenUV));
    prevColor *= border.x * border.y;

    // 3. DECAY
    float dcAmount = 0.95; 
    #ifdef u_decay
        dcAmount = u_decay;
    #endif

    // 4. FEEDBACK AMOUNT
    float fbAmount = 0.0;
    #ifdef u_feedback
        fbAmount = u_feedback;
    #endif

    // --- RESTORED TRIGGER LOGIC ---
    // Automatically enable trails on high energy
    float volume = (u_bass + u_mid + u_treble) / 3.0;

    if(volume > 0.7) {
        // Force feedback ON during high energy
        fbAmount = max(fbAmount, 0.85);
        // Make trails last slightly longer during the hit
        dcAmount = max(dcAmount, 0.96);
    }

    // Apply Decay
    prevColor *= dcAmount;

    // 5. BLEND (Max = Light Painting)
    vec3 trails = max(finalColor, prevColor);
    finalColor = mix(finalColor, trails, clamp(fbAmount, 0.0, 1.0));


    fragColor = vec4(max(vec3(0.0), finalColor), 1.0);
}

