            float d = 0.0;

            // Audio reactive time 
            float t = localTime * (1.5 * u_intensity) + u_treble * (2.0 * (0.8 + u_treble * 0.5));

            for(float i = 1.0; i <= 60.0; i++) {
                // 'f' defines a structural bounding depth scalar
                float f = abs(z - 5.0) * (0.05 * u_scale);

                // The original code packed a float and a vec3 into a vec4 just to get the length.
                // Unpacking it here is cleaner, prevents alpha-channel issues, and performs better:
                float a = dot(sin(p), sin(p / 0.6)) - length(p) + 5.0;
                vec3 b = sin(p / 0.1 + t) * cos(p.yzx / 0.1 + t) * 0.3;

                // Calculate equivalent distance safely
                float dist = sqrt(a * a + dot(b, b));

                d = (0.4 * u_intensity) * max(f, dist - f);
                z += d;

                // Color palette (d / 0.2 is replaced with d * 5.0 for multiplication speed)
                vec3 pal = cos(p.y + i * 0.2 + d * 5.0 + vec3(0.0, 1.0, (2.0 * (0.8 + u_treble * 0.5)))) + (1.1 * u_complexity);

                // SAFE: Prevent divide-by-zero causing black pixels or NaN artifacts
                col += pal / max(0.001, d);

                // Advance ray position for the NEXT iteration 
                // (This perfectly mimics Xor's third argument in the golfed for-loop)
                p = z * rayDir;
                p.z += (9.0 * u_intensity); 
            }

            float intens = 1.0;
            #ifdef u_intensity
                intens = u_intensity;
            #endif

            // Original used tanh(o*o/3e5)
            // We scale it dynamically based on the u_intensity and u_treble audio
            vec3 layerColor = tanh((col * col / 300000.0) * intens * (1.0 + u_treble * 0.2));

        layerColor *= u_amplitude * (0.8 + u_treble * 0.4);
        finalColor = blend_Screen(finalColor, layerColor, 0.5 + u_treble * 0.4);
    }

    // --- Layer 2: Plasma Waves [Liquid Noise] ---
    {
        currentUV += (vec2(finalColor.r, finalColor.g) - 0.5) * 0.01;
        vec2 layerUV = currentUV;
        float localTime = u_time * 1.0;

            vec2 p = layerUV * (4.0 * (0.8 + u_treble * 0.01));
            float n = noise(p + localTime * (0.5 * (0.4 + u_treble * 0.01)));
            n += noise(p * 2.0 - localTime) * 0.5;
            float ring = sin(n * (10.0 * u_scale) + localTime);
            vec3 layerColor = palette(n + u_treble * 0.1) * (0.5 + (0.5 * (0.48 + u_treble * 0.1)) * ring);

        layerColor *= u_amplitude * (0.8 + u_treble * 0.4);
        finalColor = blend_Add(finalColor, layerColor, 0.5 + u_treble * 0.2);
    }

    // --- Layer 3: Fractal Patterns [Sierpinski Gasket] ---
    {
        currentUV += (vec2(finalColor.r, finalColor.g) - 0.5) * 0.01 * (.10 + u_bass);
        vec2 layerUV = currentUV;
        float localTime = u_time * 0.76;

            vec2 p = layerUV * 2.0;
            p += vec2(sin(localTime * 0.3), cos(localTime * 0.4)) * 0.1;

            vec3 col = vec3(0.0);
            float scale = 1.0;

            // Iterated function system for Sierpinski
            for(int i=0; i < int(float(8) * u_complexity); i++) {
                // Fold space
                p = abs(p);

                // Rotate and scale
                float angle = localTime * 0.1 + float(i) * 0.2;
                p = rotate(p, angle);

                // Scale
                p = p * 2.0 - vec2(1.0, 0.0);

                // Accumulate color
                vec3 pal = cos(p.x + vec3(1.0, 2.0, (3.0 * u_complexity)) + localTime * (0.2 * (0.8 + u_bass * 0.5))) + 1.0;
                col += pal * scale * 0.1;

                scale *= 0.5;
            }

            // Audio reactivity
            col *= (0.5 + u_bass * 0.5);
            vec3 layerColor = tanh(col * 0.5);

        layerColor *= u_amplitude * (0.8 + u_bass * 0.4);
        finalColor = blend_Overlay(finalColor, layerColor, 0.5 + u_bass * 0.2);
    }




    // 4. Post Processing
    finalColor *= 1.0 + u_bass * 0.15;
    finalColor += max(vec3(0.0), finalColor * finalColor) * u_glow * 0.5;
    finalColor.rgb = mix(finalColor.rgb, finalColor.gbr, sin(u_colorShift * 2.0 + u_time) * 0.5 + 0.5);
    finalColor *= u_intensity;

    // 5. Feedback Trail (Fixed Box & Brightness)

    vec2 screenUV = gl_FragCoord.xy / u_resolution.xy;

    // 1. STATIONARY SAMPLING (Attached Trails)
    // No zoom, just a tiny bit of bass-driven diffusion to smooth the light
    vec2 diff = (vec2(random(screenUV + u_time), random(screenUV - u_time)) - 0.5) * 0.002 * u_bass;
    vec3 prevColor = texture(u_prev_frame, screenUV + diff).rgb;

    // 2. BORDER FADE (Fix Grey Box)
    vec2 border = smoothstep(vec2(0.0), vec2(0.02), screenUV) * (1.0 - smoothstep(vec2(0.98), vec2(1.0), screenUV));
    prevColor *= border.x * border.y;

    // 3. DECAY
    float dcAmount = 0.95; 
    #ifdef u_decay
        dcAmount = u_decay;
    #endif

    // 4. FEEDBACK AMOUNT
    float fbAmount = 0.0;
    #ifdef u_feedback
        fbAmount = u_feedback;
    #endif

    // --- RESTORED TRIGGER LOGIC ---
    // Automatically enable trails on high energy
    float volume = (u_bass + u_mid + u_treble) / 3.0;

    if(volume > 0.7) {
        // Force feedback ON during high energy
        fbAmount = max(fbAmount, 0.85);
        // Make trails last slightly longer during the hit
        dcAmount = max(dcAmount, 0.96);
    }

    // Apply Decay
    prevColor *= dcAmount;

    // 5. BLEND (Max = Light Painting)
    vec3 trails = max(finalColor, prevColor);
    finalColor = mix(finalColor, trails, clamp(fbAmount, 0.0, 1.0));


    fragColor = vec4(max(vec3(0.0), finalColor), 1.0);
}

