            vec3 layerColor = col * (0.8 + u_treble * (0.5 * u_intensity));

        layerColor *= u_amplitude * (0.8 + u_treble * 0.4);
        finalColor = blend_SoftLight(finalColor, layerColor, 0.5 + u_treble * 0.2);
