                 o += sin(p.y - localTime + vec4((6.0 * u_rotation), 1.0, 2.0, (3.0 * (0.8 + u_mid * 0.5)))) * f + f;
             }
             vec3 layerColor = tanh(o.rgb * o.rgb / (100.0 * (0.8 + u_mid * 0.5))) * (0.5 + u_mid);

        layerColor *= u_amplitude * (0.8 + u_mid * 0.4);
        finalColor = blend_Difference(finalColor, layerColor, 0.5 + u_mid * 0.2);
    }

    // --- Layer 4: Crystal Structures [Radial Facets] ---
    {
        vec2 layerUV = currentUV;
        float localTime = u_time * u_speed * 0.97;

            vec2 p = layerUV;
            float a = atan(p.y, p.x);
            float r = length(p);
            float c = cos(a * 6.0);
