            vec2 p = layerUV * (4.0 * u_complexity);
            float n = noise(p + localTime * (0.5 * u_symmetry));
            n += noise(p * (2.0 * u_complexity) - localTime) * 0.5;
            float ring = sin(n * 10.0 + localTime);
            vec3 layerColor = palette(n + u_treble * (0.5 * (0.8 + u_treble * 0.5))) * ((0.5 * u_symmetry) + 0.5 * ring);

        layerColor *= u_amplitude * (0.8 + u_treble * 0.4);
        finalColor = blend_Add(finalColor, layerColor, 0.5 + u_treble * 0.2);
    }

    // --- Layer 3: Tunnel Effect [Warp Speed] ---
    {
        currentUV = initialUV;
        vec2 layerUV = currentUV;
        float localTime = u_time * u_speed * 1.09;

            float r = length(layerUV);
            float a = atan(layerUV.y, layerUV.x);
            float stars = 0.0;
            for(float i=1.0; i<4.0; i++) {
                float t = localTime * i + 100.0;
                float depth = fract(1.0/r + t);
                float size = (0.05 * u_symmetry) * i * r;
                float angle_seed = floor(a * 10.0 * i);
                if(random(vec2(angle_seed, floor(depth*10.0))) > 0.95) {
                     stars += 1.0 / (abs(fract(depth*(10.0 * (0.8 + u_bass * 0.5))) - 0.5) * 20.0);
                }
            }
            vec3 layerColor = vec3(stars) * (0.5 + 0.5*u_bass);

        layerColor *= u_amplitude * (0.8 + u_bass * 0.4);
        finalColor = blend_SoftLight(finalColor, layerColor, 0.5 + u_bass * 0.2);
    }

    // --- Layer 4: Wave Patterns [Sliding Interference] ---
    {
        currentUV += (vec2(finalColor.r, finalColor.g) - 0.5) * 0.1 * (1.0 + u_bass);
        vec2 layerUV = currentUV;
        float localTime = u_time * u_speed * 0.62;

            vec2 p = layerUV * 4.0; // Scale up
            float PI = 3.14159;
            float t = localTime * (2.0 * u_symmetry) + u_bass * 2.0; // Audio reactive speed

            // 1. Color Palette Logic
            vec3 pal = cos(p.x / 0.6 - p.y + vec3((6.0 * u_intensity), 1.0, 2.0));

            // 2. Sliding Bands Logic
            float bandIndex = round(p.y / PI) * PI;
            float direction = cos(bandIndex); 
            float slide = cos(p.x - t * direction + (u_bass * (0.5 * (0.8 + u_bass * 0.5))));

            // 3. Vertical Interference
            float structure = cos(p.y);

            // Combine
            vec3 col = 0.3 * pal * slide / (structure + 0.01) + u_bass * 0.3;

            vec3 layerColor = tanh(col);

        layerColor *= u_amplitude * (0.8 + u_bass * 0.4);
        finalColor = blend_Add(finalColor, layerColor, 0.5 + u_bass * 0.2);
    }

    // --- Layer 5: Lightning & Electric [Spectral Tesla] ---
    {
        currentUV += (vec2(finalColor.r, finalColor.g) - 0.5) * 0.1 * (1.0 + u_bass);
        vec2 layerUV = currentUV;
        float localTime = u_time * u_speed * 1.43;

            float r = length(layerUV);
            float a = atan(layerUV.y, layerUV.x);
            float f = getFreq(abs(a) / (3.14159 * (0.8 + u_bass * 0.5)));
            float n = noise(layerUV * 10.0 + localTime * 5.0);
            float bolt = abs(a - (floor(a * (8.0 * u_intensity)) / (8.0 * u_complexity)) - sin(r * 20.0 + n * 5.0) * 0.05);
            float intensity = 0.01 / (bolt + (0.001 * u_intensity)) * f * (2.0 * u_complexity);
            intensity *= smoothstep(f + 0.1, f, r);
            vec3 layerColor = vec3(0.6, 0.8, 1.0) * intensity;
            layerColor += palette(f + localTime) * intensity * 0.5;

        layerColor *= u_amplitude * (0.8 + u_bass * 0.4);
        finalColor = blend_Exclusion(finalColor, layerColor, 0.5 + u_bass * 0.2);
    }


    // 4. Post Processing
    finalColor *= 1.0 + u_bass * 0.15;
    finalColor += max(vec3(0.0), finalColor * finalColor) * u_glow * 0.5;
    finalColor.rgb = mix(finalColor.rgb, finalColor.gbr, sin(u_colorShift * 2.0 + u_time) * 0.5 + 0.5);
    finalColor *= u_intensity;

    // 5. Feedback Trail (Fixed Box & Brightness)

    vec2 screenUV = gl_FragCoord.xy / u_resolution.xy;

    // 1. STATIONARY SAMPLING (Attached Trails)
    // No zoom, just a tiny bit of bass-driven diffusion to smooth the light
    vec2 diff = (vec2(random(screenUV + u_time), random(screenUV - u_time)) - 0.5) * 0.002 * u_bass;
    vec3 prevColor = texture(u_prev_frame, screenUV + diff).rgb;

    // 2. BORDER FADE (Fix Grey Box)
    vec2 border = smoothstep(vec2(0.0), vec2(0.02), screenUV) * (1.0 - smoothstep(vec2(0.98), vec2(1.0), screenUV));
    prevColor *= border.x * border.y;

    // 3. DECAY
    float dcAmount = u_decay;

    // 4. FEEDBACK AMOUNT
    float fbAmount = u_feedback;

    // --- RESTORED TRIGGER LOGIC ---
    // Automatically enable trails on high energy
    float volume = (u_bass + u_mid + u_treble) / 3.0;

    if(volume > 0.7) {
        // Force feedback ON during high energy
        fbAmount = max(fbAmount, 0.85);
        // Make trails last slightly longer during the hit
        dcAmount = max(dcAmount, 0.96);
    }

    // Apply Decay
    prevColor *= dcAmount;

    // 5. BLEND (Max = Light Painting)
    vec3 trails = max(finalColor, prevColor);
    finalColor = mix(finalColor, trails, clamp(fbAmount, 0.0, 1.0));


    fragColor = vec4(max(vec3(0.0), finalColor), 1.0);
}
